package com.syscore.ecosched.controller;
import com.syscore.ecosched.entity.EWaste; import com.syscore.ecosched.repository.EWasteRepository; import com.syscore.ecosched.service.ImageStorageService; import jakarta.servlet.http.HttpServletRequest; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.nio.file.*;
@RestController @RequestMapping("/api/images") public class ImageController { private final EWasteRepository items; private final ImageStorageService storage; private final AuthController auth; public ImageController(EWasteRepository i,ImageStorageService s,AuthController a){items=i;storage=s;auth=a;} @GetMapping("/{itemId}") public ResponseEntity<Resource> get(@PathVariable Long itemId,HttpServletRequest req)throws Exception{EWaste e=items.findById(itemId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!auth.admin(req)&&!e.getUser().getUserId().equals(auth.current(req).getUserId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(e.getImagePath()==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);Path p=storage.resolve(e.getImagePath());Resource r=new UrlResource(p.toUri());if(!r.exists())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return ResponseEntity.ok().contentType(MediaType.parseMediaType(Files.probeContentType(p))).body(r);}}
